def regions(g):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and (i,j) not in seen:
                c=g[i][j]; st=[(i,j)]; comp=[]
                while st:
                    a,b=st.pop()
                    if (a,b) in seen: continue
                    seen.add((a,b)); comp.append((a,b))
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dx,b+dy
                        if 0<=x<H and 0<=y<W and g[x][y]==c and (x,y) not in seen: st.append((x,y))
                out.append((c,comp))
    return out
