def largest_square(g):
    H,W=len(g),len(g[0]); best=(0,0,0,0)
    for s in range(min(H,W),0,-1):
        for i in range(H-s+1):
            for j in range(W-s+1):
                c=g[i][j]
                if c and all(g[i+a][j+b]==c for a in range(s) for b in range(s)):
                    return s,c,(i,j)
    return None
